"""Class 8 Maths Ch 14 - Area (rectangle, triangle, parallelogram, trapezium, rhombus, composite figures)."""
from c8m_u import *

SLUG, NAME, CHNO = "Area", "Area", 14

def I(x):
    x = Fr(x); assert x.denominator == 1, x; return int(x)
def ar(x, u="cm"): return f"{g(x)} {u}²"
def NA(q, v, why, u="cm", wrong=None):
    """numeric MCQ answer with area unit"""
    return ND(q, v, why, wrong=wrong, post=f" {u}²")

