e1 = [NA(f"The area of a rectangle {l} cm long and {b} cm broad is:", l * b, f"${l}\\times{b}$", wrong=[2 * (l + b), l + b, l * b + l]) for l, b in [(12, 7), (15, 8), (9, 6), (18, 5), (14, 10), (20, 3)]]
