HARD_C = ([Q(f"The perimeter of a rectangular plot is {2*(l+b)} m and its length is {k} times its breadth. Find its area and the cost of fencing at ₹ {r} per metre.", f"$b={b}$ m, $l={l}$ m (1); area $={l*b}$ m² (1); fencing cost $={2*(l+b)}\\times{r}=$ ₹ {2*(l+b)*r} (1).", "1+1+1") for l, b, k, r in [(60, 20, 3, 15), (72, 18, 4, 12), (75, 15, 5, 20), (84, 21, 4, 10), (54, 18, 3, 25), (90, 18, 5, 8)]]
         + [Q(f"An isosceles trapezium has parallel sides {a} cm and {a+2*d} cm and each slant side {c} cm. Find its height and area.", f"Height $=\\sqrt{{{c}^2-{d}^2}}={h}$ cm (2); area $=\\frac12\\times({a}+{a+2*d})\\times{h}={g(Fr((2*a+2*d)*h,2))}$ cm² (1).", "2+1") for a, d, c, h in [(14, 9, 15, 12), (20, 12, 20, 16), (16, 7, 25, 24), (18, 8, 17, 15), (22, 10, 26, 24), (30, 15, 25, 20)] if c * c - d * d == h * h]
         + [Q(f"A garden {l} m by {b} m has a rectangular pond {c} m by {d} m inside it and a path {w} m wide around the garden (outside). Find the area of the garden excluding the pond, and the area of the path.", f"Garden $-$ pond $={l*b}-{c*d}={l*b-c*d}$ m² (1); path $=({l}+{2*w})({b}+{2*w})-{l*b}={(l+2*w)*(b+2*w)-l*b}$ m² (2).", "1+2") for l, b, c, d, w in [(40, 30, 10, 8, 2), (50, 35, 12, 9, 3), (60, 40, 15, 10, 2), (36, 28, 9, 6, 1), (45, 32, 10, 10, 2), (70, 50, 20, 12, 3)]])
HARD_D = ([Q(f"The area of a rhombus is {2*a*b} cm² and one diagonal is {2*a} cm. Find the other diagonal, the side, and the altitude.", f"Other diagonal $=2\\times{2*a*b}/{2*a}={2*b}$ cm (2); side $=\\sqrt{{{a}^2+{b}^2}}={c}$ cm (1); altitude $={2*a*b}/{c}={g(Fr(2*a*b,c))}$ cm (2).", "2+1+2") for a, b, c in [(9, 12, 15), (12, 16, 20), (15, 20, 25), (3, 4, 5), (6, 8, 10), (18, 24, 30)]]
          + [Q(f"A trapezium ABCD has parallel sides AB = {a} cm and DC = {b} cm and height {h} cm. A parallelogram of base {a} cm and the same height is cut off from it, leaving a triangle. Find the area of the trapezium, the parallelogram and the remaining triangle.", f"Trapezium $=\\frac12({a}+{b})\\times{h}={g(Fr((a+b)*h,2))}$ cm² (2); parallelogram $={a*h}$ cm² (1); triangle $=\\frac12\\times{b-a}\\times{h}={g(Fr((b-a)*h,2))}$ cm² (2).", "2+1+2") for a, b, h in [(14, 26, 10), (18, 30, 8), (20, 32, 12), (12, 28, 9), (16, 34, 6), (22, 40, 14)]])

def T(A, B, C, D): return dict(A=A, B=grp(B, 4), C=grp(C, 6), D=grp(D, 6))
TIERS = {"NCERT": T(NCERT_A, NCERT_B, NCERT_C, NCERT_D), "Easy": T(EASY_A, EASY_B, EASY_C, EASY_D),
         "Medium": T(MED_A, MED_B, MED_C, MED_D), "Hard": T(HARD_A, HARD_B, HARD_C, HARD_D)}
